-- Ragefire Chasm / Deadmines
Lang["N1_11519"] = "Баззалан"
Lang["N2_11519"] = "Баззалан — босс-сатир на верхнем уступе над Жергошем в Огненной Пропасти."
Lang["N1_11518"] = "Жергош Призыватель"
Lang["N2_11518"] = "Жергош Призыватель — босс-чернокнижник в глубине Огненной Пропасти."
Lang["N1_11520"] = "Тарагаман Ненасытный"
Lang["N2_11520"] = "Тарагаман Ненасытный — босс-страж Скверны в лавовом озере Огненной Пропасти."
Lang["N1_11834"] = "Маур Зловещий Тотем"
Lang["N2_11834"] = "Тело Маура Зловещего Тотема лежит за первым боссом в Огненной Пропасти, справа от основного пути."
Lang["N1_639"] = "Эдвин ван Клиф"
Lang["N2_639"] = "Эдвин ван Клиф — финальный босс Мёртвых копей, на пиратском корабле в Бухте Брони."
-- Shadowfang Keep
Lang["N1_4275"] = "Верховный маг Аругал"
Lang["N2_4275"] = "Верховный маг Аругал — финальный босс Крепости Темного Клыка, на вершине крепости. Черный фолиант лежит на столе позади него."
Lang["N1_3849"] = "Страж смерти Адамант"
Lang["N2_3849"] = "Тело стража смерти Адаманта лежит в начале Крепости Темного Клыка, в боковой комнате у двора."
Lang["N1_4444"] = "Страж смерти Винсент"
Lang["N2_4444"] = "Тело стража смерти Винсента находится глубже в Крепости Темного Клыка, рядом со столовой."
-- Blackfathom Deeps
Lang["N1_4787"] = "Страж Талрид из ордена Серебряного Рассвета"
Lang["N2_4787"] = "Страж Талрид находится в Непроглядной Пучине, за первыми пещерами наг."
Lang["N1_4832"] = "Повелитель сумрака Келрис"
Lang["N2_4832"] = "Повелитель сумрака Келрис — босс Непроглядной Пучины, в святилище Луны."
Lang["N1_12902"] = "Лоргус Джетт"
Lang["N2_12902"] = "Лоргус Джетт — заклинатель Сумеречного Молота в Непроглядной Пучине, на пути к святилищу."
-- Gnomeregan
Lang["N1_7800"] = "Мекжинер Термоштепсель"
Lang["N2_7800"] = "Мекжинер Термоштепсель — финальный босс Гномрегана, в Дворе механиков."
Lang["N1_6231"] = "Техбот"
Lang["N2_6231"] = "Техбот стоит у входа в Гномреган, снаружи подземелья."
Lang["N1_7850"] = "Керноби"
Lang["N2_7850"] = "Керноби находится в Гномрегане и начинает задание на сопровождение «Круговерть судеб»."
-- Razorfen Kraul
Lang["N1_4421"] = "Чарлга Остробок"
Lang["N2_4421"] = "Чарлга Остробок — финальный босс Лабиринтов Иглошкурых."
Lang["N1_4508"] = "Импортер Вилликс"
Lang["N2_4508"] = "Импортер Вилликс находится в Лабиринтах Иглошкурых и его нужно сопроводить наружу."


Lang["O_1"] = "Используйте \"Клеймо Драккисата\", чтобы завершить квест.\nЭто светящийся шар, расположенный позади генерала Драккисата - последний босс, которого Вы встретите в рейдовом подземелье \"Верхняя часть пика Черной Горы (UBRS)\"."
Lang["O_2"] = "Это крошечная светящаяся красная точка на земле перед вратами Ан'Киража (28.7,89.2)."
