Lang["Q2_2928"] = "Принесите Шони в Штормград 24 горсти механических внутренностей роботов."
Lang["Q2_2929"] = "Отправляйтесь в Гномреган и убейте Мекжинера Термоштепселя. Вернитесь к Главному Механику Меггакруту."
