Lang["Q2_3341"] = "Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп."
Lang["Q2_3369"] = "Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин."
