Lang["Q2_447"] = "Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их мастеру-аптекарю Фаранеллу в Подгород."
Lang["Q2_450"] = "Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу."
Lang["Q2_451"] = "Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихохода и твердую опухоль мастеру-аптекарю Фаранеллу в Подгород."
Lang["Q2_3520"] = "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля."
Lang["Q2_3523"] = "Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам."
Lang["Q2_3525"] = "Сопроводите Белнистраза к идолу свинобразов на Курганах Иглошкурых."
Lang["Q2_3527"] = "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис."
Lang["Q2_3528"] = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис."
