Lang["Q2_3636"] = "Убейте Амненнара Хладовея на Курганах Иглошкурых."
Lang["Q2_3681"] = "Speak with Duthorian Rall in Stormwind."
Lang["Q2_3701"] = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."
Lang["Q2_3702"] = "Listen to Royal Historian Archesonus recant the history of Thaurissan."
Lang["Q2_373"] = "Доставьте письмо городскому архитектору Баросу Алекстону в Штормград."
Lang["Q2_377"] = "Принесите советнику Миллстайпу руку Декстрена Варда."
Lang["Q2_386"] = "Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье."
Lang["Q2_387"] = "Тюремщик Телвотер просит вас убить в тюрьме 10 узников из Братства Справедливости, 8 каторжников из Братства Справедливости и 8 мятежников из Братства Справедливости."
Lang["Q2_388"] = "Принесите Никове Раскол 10 красных шерстяных бандан."
Lang["Q2_389"] = "Поговорите с надзирателем Телвотером в тюрьме."
Lang["Q2_3906"] = "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду."
Lang["Q2_3907"] = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию."
Lang["Q2_391"] = "Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда."
Lang["Q2_3911"] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."
Lang["Q2_3981"] = "Найдите командира Гор'шака в Глубинах Черной горы."
Lang["Q2_4001"] = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар."
Lang["Q2_4002"] = "Поговорите с Траллом."
Lang["Q2_4003"] = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия."
Lang["Q2_4004"] = "Вернитесь к Траллу."
Lang["Q2_4022"] = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade."
Lang["Q2_4024"] = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора."
Lang["Q2_4063"] = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии."
Lang["Q2_4081"] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!"
Lang["Q2_4082"] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!"
Lang["Q2_4123"] = "Принесите сердце горы Максворту Суперблеску в Пылающие степи."
Lang["Q2_4126"] = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос."
Lang["Q2_4128"] = "Speak with Ragnar Thunderbrew."
Lang["Q2_4134"] = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат."
Lang["Q2_4136"] = "Принесите голову Риббли Юке Крутипроб в Пылающие степи."
Lang["Q2_4201"] = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы."
Lang["Q2_4262"] = "Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке."
Lang["Q2_4263"] = "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!"
Lang["Q2_4286"] = "Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы."
Lang["Q2_4341"] = "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота."
