Lang["Q2_4489"] = "Поговорите в Кабестане со Страхадом Фарсаном."
Lang["Q2_4490"] = "Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны."
Lang["Q2_463"] = "Find the Greenwarden in the Wetlands."
Lang["Q2_469"] = "Bring the bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor."
Lang["Q2_4701"] = "Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами."
Lang["Q2_4724"] = "Убейте Халикон, праматерь стаи воргов Кровавого Топора."
Lang["Q2_4729"] = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру."
Lang["Q2_4734"] = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье."
Lang["Q2_4735"] = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."
Lang["Q2_4736"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4737"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4738"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4739"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4742"] = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения."
Lang["Q2_4743"] = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю."
Lang["Q2_4764"] = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи."
Lang["Q2_4766"] = "Поговорите с Майрой в Пылающих степях."
Lang["Q2_4768"] = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат."
Lang["Q2_4769"] = "Переговорите с темным магом Вивианой Лягроб."
Lang["Q2_4771"] = "Поместите Рассветный гамбит в демонстрационную комнату в Некроситете. Уничтожьте Вектуса, затем возвращайтесь к Бетине Биггльцинк."
Lang["Q2_4781"] = "Отнесите слиток золота Зиску Ладноскрою в Тернистую долину."
Lang["Q2_4782"] = "Возвращайтесь к Менаре Расщепительнице Бездны в Степи."
Lang["Q2_4783"] = "Принесите 10 фиалов крови сатира из племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Менара Расщепительнице Бездны."
Lang["Q2_4784"] = "Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души."
Lang["Q2_4785"] = "Fine Gold Thread"
Lang["Q2_4786"] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней."
Lang["Q2_4787"] = "Принесите древнее яйцо Йе'кинье в Танарис."
Lang["Q2_4788"] = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе."
Lang["Q2_5065"] = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарисе."
Lang["Q2_4862"] = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука."
Lang["Q2_4866"] = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд."
Lang["Q2_4867"] = "Прочитайте записку Вароша. Принесите Варошу его амулет."
Lang["Q2_4961"] = "Убейте демона сферы, а потом поговорите с Табетой."
Lang["Q2_4962"] = "Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей."
Lang["Q2_4963"] = "Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей."
Lang["Q2_4964"] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней."
Lang["Q2_4965"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4967"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4968"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4969"] = "Поговорите с Менарой Расщепительницей Бездны в Степях."
Lang["Q2_4975"] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней."
Lang["Q2_4976"] = "Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи."
Lang["Q2_4981"] = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой."
Lang["Q2_4982"] = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья."
Lang["Q2_4983"] = "Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат."
Lang["Q2_5001"] = "Найдите вещи Блестяшки и верните их владелице. Удачи!"
Lang["Q2_5002"] = "Передайте маршалу Максвеллу информацию Блестяшки."
Lang["Q2_5047"] = "Переговорите с Малифоем Черномолотом в Круговзоре."
Lang["Q2_5061"] = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion."
Lang["Q2_5081"] = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу."
Lang["Q2_5089"] = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи."
Lang["Q2_5102"] = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу."
Lang["Q2_5125"] = "Bring the Medallion of Faith to Aurius in Stratholme. After Baron Rivendare falls, speak with Aurius."
Lang["Q2_5160"] = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби."
Lang["Q2_5212"] = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат."
Lang["Q2_5213"] = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк."
Lang["Q2_5214"] = "Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней пачку лучшего табака Гримма и принесите ее Дымку ЛаРу."
Lang["Q2_5243"] = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно."
Lang["Q2_5251"] = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых."
Lang["Q2_5262"] = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли."
Lang["Q2_5263"] = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу."
Lang["Q2_5281"] = "Найдите Эгана. В последний раз его видели недалеко от Стратхольма."
Lang["Q2_5282"] = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу."
Lang["Q2_5341"] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову."
Lang["Q2_5342"] = "Отправляйтесь в Лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову."
Lang["Q2_5343"] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову."
Lang["Q2_5344"] = "Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Велдону Барову."
Lang["Q2_5382"] = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф."
Lang["Q2_5384"] = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос."
Lang["Q2_544"] = "Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянью Бездны в Мельницу Таррен."
Lang["Q2_545"] = "Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянью Бездны на мельницу Таррен."
Lang["Q2_5461"] = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку."
Lang["Q2_5462"] = "Отправляйтесь в часовню Последней Надежды в Восточных Чумных землях и найдите Леонида Барталомея Чтимого. Покажите ему книгу воспоминаний и расскажите обо всем, о чем удалось узнать."
Lang["Q2_5463"] = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю."
Lang["Q2_5466"] = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку."
Lang["Q2_5515"] = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф."
Lang["Q2_5522"] = "Отнесите замороженные яйца Леониду Барталомею в Восточные Чумные земли."
Lang["Q2_5526"] = "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне."
Lang["Q2_5529"] = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды."
Lang["Q2_5531"] = "Отнесите замороженные яйца Бетине Биггльцинк."
Lang["Q2_5582"] = "Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли."
