Lang["Q2_5722"] = "Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы."
Lang["Q2_5723"] = "Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес."
Lang["Q2_5724"] = "Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес."
Lang["Q2_5725"] = "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматрасу в Подгород."
Lang["Q2_5726"] = "Принесите лейтенантский знак отличия Траллу в Оргриммар."
Lang["Q2_5727"] = "Отнесите лейтенантский знак отличия Нииру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар."
Lang["Q2_5728"] = "Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу."
Lang["Q2_5729"] = "Поговорите с Нииру Огненным Клинком в Оргриммаре."
Lang["Q2_5730"] = "Поговорите с Траллом в Оргриммаре."
Lang["Q2_5742"] = "Выслушайте Тириона Фордринга."
Lang["Q2_5761"] = "Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре."
Lang["Q2_5781"] = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу."
Lang["Q2_5845"] = "Отправляйтесь в Северный Дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу."
Lang["Q2_5846"] = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину."
Lang["Q2_5848"] = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира."
Lang["Q2_5921"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5922"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5923"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
