Lang["Q2_6076"] = "Speak with Grif Wildheart in Kharanos."
Lang["Q2_6081"] = "Speak with Ormak Grimshot in Orgrimmar."
Lang["Q2_6082"] = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill."
Lang["Q2_6083"] = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill."
Lang["Q2_6084"] = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos."
Lang["Q2_6085"] = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
Lang["Q2_6086"] = "Speak with Belia Thundergranite in Ironforge."
Lang["Q2_6087"] = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6088"] = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6089"] = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."
Lang["Q2_6101"] = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6102"] = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6103"] = "Speak to Jocaste in the Cenarion Enclave, in Darnassus."
Lang["Q2_6121"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6122"] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."
Lang["Q2_6123"] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."
Lang["Q2_6124"] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."
Lang["Q2_6125"] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_6126"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6127"] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."
Lang["Q2_6128"] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."
Lang["Q2_6129"] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."
Lang["Q2_6130"] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff."
Lang["Q2_6133"] = "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен. Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников."
Lang["Q2_6135"] = "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостню. Говорят, Тенекрыл рыщет в землях к северу от имения Марриса."
Lang["Q2_6136"] = "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостню по выполнению задания."
Lang["Q2_6141"] = "Найдите в Пустошах брата Антона и поговорите с ним."
Lang["Q2_6144"] = "Отправляйтесь в Подгород и поговорите с Вариматрасом."
Lang["Q2_6163"] = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира."
Lang["Q2_63"] = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."
Lang["Q2_65"] = "Поговорите с Вилли в Приозерье по просьбе Гриана Камнегрива."
Lang["Q2_6521"] = "Принести голову посла Малкина Вариматрасу в Подгород."
Lang["Q2_6522"] = "Отнесите маленький свиток Вариматрасу в Подгород."
Lang["Q2_65593"] = "Принесите сердца Авелины Лилли и Исаака Пирсона Карнедину Халгару в Храм Проклятых."
Lang["Q2_65597"] = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity."
Lang["Q2_65601"] = "Speak with Magar in Orgrimmar."
Lang["Q2_65602"] = "Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда."
Lang["Q2_65603"] = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb."
Lang["Q2_65604"] = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar."
Lang["Q2_6561"] = "Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес."
Lang["Q2_65610"] = "Осмотрите озеро Зеркало Небес в Ясеневом лесу и расскажите о находках Ган'рулу Кровавый Глаз в Оргриммаре."
Lang["Q2_6562"] = "Поговорите с Дже'неу Санкри в Ясеневом лесу."
Lang["Q2_6563"] = "Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес."
Lang["Q2_6564"] = "Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес."
Lang["Q2_6565"] = "Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес."
Lang["Q2_6626"] = "Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых."
Lang["Q2_6627"] = "Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах."
Lang["Q2_6628"] = "Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде."
Lang["Q2_6681"] = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared."
Lang["Q2_6701"] = "Syndicate Emblems"
Lang["Q2_6921"] = "Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес."
Lang["Q2_6922"] = "Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу."
Lang["Q2_6981"] = "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке."
Lang["Q2_7028"] = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей."
Lang["Q2_7029"] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона."
Lang["Q2_7041"] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона."
Lang["Q2_7044"] = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса."
Lang["Q2_7046"] = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса."
Lang["Q2_7064"] = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах."
Lang["Q2_7065"] = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши."
Lang["Q2_7066"] = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни."
Lang["Q2_7067"] = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей."
Lang["Q2_7068"] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар."
Lang["Q2_7070"] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей."
Lang["Q2_709"] = "Принесите табличку Рьюн'эха Тельдарину Заблудшему."
Lang["Q2_720"] = "Найдите геолога Ржавца и сообщите ему, что Грез Тяжелоступ жив."
Lang["Q2_7201"] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."
Lang["Q2_721"] = "Найдите Греза Тяжелоступа в Ульдамане."
Lang["Q2_722"] = "Найдите амулет Тяжелоступа и верните его ему в Ульдаман."
Lang["Q2_7441"] = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина."
Lang["Q2_7461"] = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется."
Lang["Q2_7462"] = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!"
Lang["Q2_7481"] = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать."
Lang["Q2_7482"] = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к школяру Рунному Шипу и сообщите ей все, что вам удалось узнать."
Lang["Q2_7488"] = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе."
Lang["Q2_7489"] = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе."
Lang["Q2_7492"] = "Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе."
Lang["Q2_7494"] = "Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе."
Lang["Q2_7499"] = "Return the book to its rightful owners."
Lang["Q2_7506"] = "Return the book to its rightful owners."
Lang["Q2_7562"] = "Поговорите с Мор'зулом Кровопуском в Пылающих степях."
Lang["Q2_7563"] = "Принесите 30 бутылок крови яростных зверей Мор'зулу Кровопуску в Пылающие степи."
Lang["Q2_7564"] = "Принесите ларец Крови Горзиеки Дикоглазу в Пылающие степи."
Lang["Q2_7581"] = "Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего шрама по выполнении поручения."
Lang["Q2_7582"] = "Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего шрама по выполнении поручения."
Lang["Q2_7583"] = "Отправляйтесь в Гниющий шрам и и найдите командира стражников ужаса.\n\nПри помощи светящегося кристалла заточения поймайте командира стражников ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения.\n\nЕсли вы добьетесь успеха, отнесите пленного стражника ужаса Дайо в Гниющий шрам."
Lang["Q2_7601"] = "Поговорите с Бесенком в Оскверненном лесу."
Lang["Q2_7602"] = "Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.\n\nБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.\n\nДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес."
Lang["Q2_7603"] = "Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.\n\nПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес."
Lang["Q2_7621"] = "A Warning"
Lang["Q2_7622"] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain."
Lang["Q2_7623"] = "Купите зелья Теней у Горзиеки в Пылающих степях.\n\nПриняв зелья, пройдите в Джеденар и поговорите с лордом Гиблопустом."
Lang["Q2_7624"] = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар."
Lang["Q2_7625"] = "Купите зоротианскую звездную пыль у Ур'Дана. Отнесите ее Горзиеки Дикоглазу в Пылающие степи."
Lang["Q2_7626"] = "Отнесите 10 эликсиров Силы Теней Горзиеки Дикоглазу в Пылающие степи."
Lang["Q2_7627"] = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи."
Lang["Q2_7628"] = "Принесите 35 шкур черного дракона Горзиеки Дикоглазу в Пылающие степи."
Lang["Q2_7629"] = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу."
Lang["Q2_7630"] = "Принесите 3 арканитовых слитка Горзиеки в Пылающие степи."
Lang["Q2_7631"] = "Прочтите инструкции Мор'зула. Призовите ксоротианского коня погибели, одолейте его и подчините его дух."
Lang["Q2_7632"] = "Find the owner of the Ancient Petrified Leaf. Good luck, you; It's a big world."
Lang["Q2_7633"] = "An Introduction"
Lang["Q2_7634"] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."
Lang["Q2_7635"] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."
Lang["Q2_7636"] = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself."
Lang["Q2_7637"] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."
Lang["Q2_7638"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_7639"] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7640"] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7641"] = "Speak with Grimand Elmore in Stormwind's Dwarven District."
Lang["Q2_7642"] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."
Lang["Q2_7643"] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."
Lang["Q2_7644"] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7645"] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities."
Lang["Q2_7646"] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7647"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."
Lang["Q2_7648"] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."
Lang["Q2_7666"] = "Again Into the Great Ossuary"
