Lang["Q2_79007"] = "Отправляйтесь к 46, 73 в Степях. Взаимодействуйте с обгоревшими останками и примите задание.\n\nСдайте его у 37, 50 в Западном Крае, взаимодействовав с прибитой доской. Примите «Каменные ступени» у этой доски, прежде чем уйти."
Lang["Q2_79008"] = "Отправляйтесь к 37, 50 в Западном Крае. Взаимодействуйте с обгоревшими останками рядом с прибитой доской и примите задание.\n\nСдайте его у 46, 73 в Степях, у обгоревших останков, затем взаимодействуйте там с прибитой доской и примите «Каменные ступени»."
Lang["Q2_79192"] = "Орда принимает это у прибитой доски на 37, 50 в Западном Крае. Альянс принимает это у прибитой доски на 46, 73 в Степях.\n\nОтправляйтесь к 51, 51 в Когтистых горах. С дороги пройдите в проход в горах и следуйте по тропе до лагеря. Взаимодействуйте с содержимым карманов (40.8, 52.5)."
Lang["Q2_79974"] = "Взаимодействуйте с кучей земли в Когтистых горах (39.6, 49.9), чтобы принять это задание.\n\nОтправляйтесь к дамбе у 49, 12 в Лок Модане. Спрыгните на уступ и взаимодействуйте с резной фигуркой (49.5, 12.8)."
Lang["Q2_79975"] = "Взаимодействуйте с резной фигуркой у дамбы Лок Модана (49.5, 12.8), чтобы принять это задание.\n\nОтправляйтесь к 81, 56 в Предгорьях Хилсбрада. Стоя лицом к воротам в Нагорье Арати, поверните налево и идите вдоль стены до упавшей повозки. Пройдите прыжковую головоломку к лагерю и взаимодействуйте с сумкой посыльного (Нагорье Арати 22.4, 24.2)."
Lang["Q2_79976"] = "Взаимодействуйте с сумкой посыльного, затем с наспех свернутой сумкой прямо под ней, чтобы получить Уютный спальный мешок."
Lang["Q2_79980"] = "В лагере Когтистых гор взаимодействуйте с содержимым карманов (40.8, 52.5), чтобы принять это задание.\n\nПробегите через лагерь и спрыгните с гор на уступ с кучей земли (39.6, 49.9), затем взаимодействуйте с ней."
Lang["Q2_79987"] = "Можете оставить кольцо себе или найти того, кто оставил оттиск и гравировку на его внутренней стороне."
